{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen/play/users/u046/system/state/workspace/programs/task-a1582562.py",
 "content": "def transform(grid):
    """Replace isolated target markers with the vertical motif from the exemplar."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Identify isolated marker color: the color with many singleton cells
    # against a uniform background. The exemplar marker is the central 3 of
    # a vertical 4-0-4 strip; tests encode that same marker as 6.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    marker = max((v for v in counts if v != bg), key=lambda v: counts[v])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr, value in ((-1, 4), (0, 0), (1, 4)):
                    rr = r + dr
                    if 0 <= rr < h:
                        out[rr][c] = value
    return out
"
